mapper.select:
SELECT tr.trip_region_id, tr.trip_region_code, tr.trip_region_name, tr.latitude, tr.longitude, tr.use_yn, tr.created_at FROM trip_region tr INNER JOIN trip t ON t.trip_id = #{tripId} AND t.trip_region_id IS NULL LEFT JOIN trip_candidate tc ON tc.trip_region_id = tr.trip_region_id AND tc.trip_id = #{tripId} AND tc.selected_yn = 'Y'
AND tr.use_yn = 'Y' AND tc.trip_candidate_id IS NULL
ORDER BY RAND() LIMIT #{cnt}
